#!/usr/bin/env node
// gen-bounds.mjs — single source of truth for every shared tunable bound in
// the repo (read windows, output caps, span limits, gate budgets).
// Consumers are GENERATED files; never hand-edit them:
//   rust-tools/<crate>/src/bounds.gen.rs   (mod bounds; then bounds::NAME)
//   extensions/permission-gate/bounds.gen.ts (import { NAME })
//
// Change a value here, run `node scripts/gen-bounds.mjs`, commit the result.
// `node scripts/gen-bounds.mjs --check` exits 1 on drift; tests/gate/
// bounds-drift.test.mjs pins that (and config.json's H1 defaults), so an
// un-regenerated edit fails the suite.

import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

// ---------------------------------------------------------------------------
// THE TABLE. Values mirror shipped behavior; a change here is a behavior
// change and must say so in its changelog entry.
// ---------------------------------------------------------------------------
export const BOUNDS = {
  read: {
    window: { lines: 100, bytes: 8192 }, // piread read budget before a gap (inside H1b 300/8192)
    span: { capBytes: 51200 }, // piread span cap (~50 KB) before footer paging
    locate: { context: 12, pointers: 40 }, // piread fused locate+read (--hits): context lines each side of a hit; hit pointers listed in the footer
  },
  bash: {
    cap: { lines: 40, bytes: 2048 }, // pibash result cap (H1)
    read: { capLines: 300, capBytes: 8192 }, // gate H1b read-result cap
  },
  pidx: {
    inline: { chars: 2000 }, // pidx inline extract cap (PI_PIDX_MAX_INLINE)
  },
  outline: {
    show: { maxSpan: 200, head: 100, tail: 20 }, // outline --show bounds
  },
  gate: {
    diet: { chars: 220, anchorChars: 800 }, // block-reason diet caps
    big: { readBytes: 10000, readWin: 500 }, // Token Economy big-read thresholds
    locate: { minWin: 100 }, // R1c located-lookup minimum window
    remedy: { maxLines: 15, maxChars: 1500 }, // Anchor Guard remedy size
    outputCap: { maxLines: 10000, maxBytes: 10000000 }, // loader validation ceilings
    confirm: { timeoutMs: 3600000 },
  },
};

const RUST_CRATES = ["piread", "pibash", "pidx", "piedit", "outline", "docheck"];
const TS_PATH = join(ROOT, "extensions/permission-gate/bounds.gen.ts");

/** flatten {a:{b:{c:1}}} → [["a.b.c", 1]] */
function flatten(obj, prefix = "") {
  return Object.entries(obj).flatMap(([k, v]) => {
    const path = `${prefix}${k}`;
    if (v && typeof v === "object") return flatten(v, `${path}.`);
    return [[path, v]];
  });
}

const entries = flatten(BOUNDS).map(([path, value]) => ({
  path,
  constName: path
    .split(".")
    .map((s) => s.toUpperCase())
    .join("_"),
  value,
}));

function rustModule() {
  const lines = [
    "// GENERATED by scripts/gen-bounds.mjs — do not edit.",
    "// Edit BOUNDS there and run: node scripts/gen-bounds.mjs",
    "#![allow(dead_code)] // crates use a subset; the table is shared",
    "",
  ];
  for (const { path, constName, value } of entries)
    lines.push(`/// ${path} = ${value}`, `pub const ${constName}: u64 = ${value};`, "");
  return lines.join("\n");
}

function tsModule() {
  const lines = [
    "// GENERATED by scripts/gen-bounds.mjs — do not edit.",
    "// Edit BOUNDS there and run: node scripts/gen-bounds.mjs",
    "",
  ];
  for (const { path, constName, value } of entries)
    lines.push(`/** ${path} = ${value} */`, `export const ${constName} = ${value};`, "");
  return lines.join("\n");
}

function generate() {
  const written = [];
  for (const crate of RUST_CRATES) {
    const p = join(ROOT, "rust-tools", crate, "src", "bounds.gen.rs");
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, rustModule());
    written.push(p);
  }
  mkdirSync(dirname(TS_PATH), { recursive: true });
  writeFileSync(TS_PATH, tsModule());
  written.push(TS_PATH);
  return written;
}

function check() {
  const stale = [];
  const targets = [
    ...RUST_CRATES.map((c) =>
      join(ROOT, "rust-tools", c, "src", "bounds.gen.rs"),
    ),
    TS_PATH,
  ];
  for (const t of targets) {
    const want = t === TS_PATH ? tsModule() : rustModule();
    const have = existsSync(t) ? readFileSync(t, "utf8") : "(missing)";
    if (have !== want) stale.push(t);
  }
  if (stale.length) {
    console.error(`bounds drift: regenerate with node scripts/gen-bounds.mjs — ${stale.join(", ")}`);
    process.exit(1);
  }
  console.log(`bounds ok: ${targets.length} generated files match the table`);
}

if (process.argv[2] === "--check") check();
else for (const p of generate()) console.log(`wrote ${p}`);
